#include <iostream>
#include <stdexcept>
#include <string>

class Resource {
    std::string name;
public:
    Resource(const std::string& n) : name(n) {
        std::cout << "Constructed " << name << "\n";
    }
    ~Resource() {
        std::cout << "Destroyed " << name << "\n";
    }
};

class BadConfigException : public std::runtime_error {
public:
    BadConfigException(const std::string& msg) : std::runtime_error(msg) {}
};

class Server {
    Resource r1;
    Resource r2;
public:
    Server(bool fail) : r1("Resource-1"), r2("Resource-2") {
        if (fail) {
            std::cout << "Server init encountered failure!\n";
            throw BadConfigException("Port 8080 unavailable");
        }
        std::cout << "Server ready.\n";
    }
    ~Server() {
        std::cout << "Server shut down.\n";
    }
};

int main() {
    try {
        std::cout << "Attempting to boot server:\n";
        Server s(true);
    } catch (const std::exception& ex) {
        std::cout << "Caught polymorphic exception: " << ex.what() << "\n";
    }
    return 0;
}

#include <iostream>
#include <new>
#include <cstdlib>

void customNewHandler() {
    std::cout << "customNewHandler executed! Terminating via exit(0)...\n";
    std::exit(0);
}

int main() {
    // 1. Using std::nothrow
    size_t gigantic = static_cast<size_t>(-1) / 4;
    char* pNothrow = new (std::nothrow) char[gigantic];
    if (pNothrow == nullptr) {
        std::cout << "nothrow allocation failed, safely returned nullptr.\n";
    } else {
        delete[] pNothrow;
    }

    // 2. Catching std::bad_alloc
    try {
        std::cout << "Attempting impossible allocation with standard new...\n";
        char* pThrow = new char[gigantic];
        delete[] pThrow;
    } catch (const std::bad_alloc& e) {
        std::cout << "Caught expected exception: " << e.what() << "\n";
    }

    // 3. Demonstrating set_new_handler
    std::set_new_handler(customNewHandler);
    std::cout << "Triggering allocation with custom handler installed...\n";
    char* pHandler = new char[gigantic];
    delete[] pHandler;

    return 0;
}

#include <iostream>
#include <memory>
#include <stdexcept>

class Integer {
    int value;
public:
    Integer(int i = 0) : value(i) {
        std::cout << "Constructor for Integer " << value << "\n";
    }
    ~Integer() {
        std::cout << "Destructor for Integer " << value << "\n";
    }
    void setInteger(int i) { value = i; }
    int getInteger() const { return value; }
};

void riskyOperation(bool throwError) {
    std::cout << "Entering riskyOperation\n";
    // Using modern std::make_unique (C++14/17 standard practice)
    auto ptr = std::make_unique<Integer>(7);
    ptr->setInteger(99);
    std::cout << "Integer value: " << (*ptr).getInteger() << "\n";

    if (throwError) {
        std::cout << "Throwing exception during operation...\n";
        throw std::runtime_error("Something went wrong!");
    }
    std::cout << "Exiting riskyOperation normally\n";
}

int main() {
    try {
        riskyOperation(true);
    } catch (const std::exception& e) {
        std::cout << "Caught in main: " << e.what() << "\n";
    }
    std::cout << "Program finished cleanly without leaks.\n";
    return 0;
}
